      "LastName": "Nair",
      "Email": "priya.nair@example.com",
      "AccountId": "0015g00000TrAd3AAB"
    }
  ],
  "allOrNothing": true
}
###
POST /services/data/v58.0/composite HTTP/1.1
Content-Type: application/json

[
  {
    "method": "PATCH",
    "url": "/services/data/v58.0/sobjects/Account/0015g00000TrAd3AAB",
